<h2><?=e(languagePhrase('התמונה שלכם, לפי הסכומים שהזנתם','Your summary, based on the amounts entered','Итог по введённым суммам'))?></h2>
<?php if(!$result['filled']):?>
<p class="notice"><?=e(languagePhrase('עוד אין סכומים לחישוב. הוסיפו לפחות סכום ידוע או הערכה.','No amounts to calculate yet. Add at least one known cost or estimate.','Пока нечего рассчитывать. Добавьте хотя бы одну известную или приблизительную сумму.'))?></p>
<?php else:?>
<div class="result-grid"><div><?=e(languagePhrase('סכומים ידועים','Known costs','Известные расходы'))?><strong><?=amount($result['known'])?> <?=e($currency)?></strong></div><div><?=e(languagePhrase('הערכות שלכם','Your estimates','Ваши оценки'))?><strong><?=amount($result['estimate'])?> <?=e($currency)?></strong></div><div><?=e(languagePhrase('סך הסעיפים שמולאו','Total of completed items','Итого по заполненным статьям'))?><strong><?=amount($result['total'])?> <?=e($currency)?></strong></div></div>
<?php if(!empty($result['travelers'])):?><p><?=e(languagePhrase('ממוצע חשבוני לנוסע בסעיפים שמולאו:','Average per traveller for completed items:','Средняя сумма на человека по заполненным статьям:'))?> <?=amount(intdiv($result['total']+intdiv($result['travelers'],2),$result['travelers']))?> <?=e($currency)?>. <?=e(languagePhrase('זהו ממוצע תכנוני, לא תעריף ספק.','This is a planning average, not a supplier rate.','Это среднее значение для планирования, а не тариф поставщика.'))?></p><?php endif?>
<?php endif?>
<?php if($result['missing']):?><p class="notice"><?=e(languagePhrase('סעיפים חסרים:','Missing items:','Незаполненные статьи:'))?> <?=count($result['missing'])?> — <span translate="no"><?=e(implode(' · ',$result['missing']))?></span>. <?=e(languagePhrase('הסיכום אינו תקציב מלא עד להשלמתם.','The total is not a complete budget until these are filled in.','До их заполнения итог не отражает полный бюджет.'))?></p><?php else:?><p class="notice"><?=e(languagePhrase('כל הסעיפים סומנו. כדאי לחזור ולבדוק את ההערכות לפני ההזמנה.','All items have a status. Review your estimates again before booking.','Все статьи отмечены. Перед бронированием ещё раз проверьте приблизительные суммы.'))?></p><?php endif?>
